<?php require_once 'functions.php'; need_login(); $q=$pdo->prepare('SELECT * FROM diagnoses WHERE user_id=? ORDER BY created_at DESC');$q->execute([user()['id']]);$rows=$q->fetchAll();header_html('Riwayat saya');?><section class="page-head"><span class="eyebrow">CATATAN KEBUN</span><h1>Riwayat diagnosis</h1><p>Hasil diagnosis yang pernah Anda simpan.</p></section><?php if(!$rows):?><div class="empty card"><div>📋</div><h2>Belum ada riwayat</h2><p>Mulai diagnosis pertama untuk menyimpan hasil di sini.</p><a class="button" href="<?=e(app_url('diagnosis.php'))?>">Mulai diagnosis</a></div><?php else:?><div class="table-wrap card"><table><thead><tr><th>Tanggal</th><th>Kemungkinan utama</th><th>Keyakinan</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d M Y H:i',strtotime($r['created_at']))?></td><td><?=e($r['disease_name'])?></td><td><strong><?=number_format($r['confidence'],1)?>%</strong></td><td><a href="<?=e(app_url('print.php'))?>?id=<?=$r['id']?>">Lihat / cetak</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php footer_html();?>
